using TMPro; using UnityEngine; using UnityEngine.UI;
namespace Demo.Inventory { public sealed class ItemDetailPanel:MonoBehaviour { [SerializeField] TMP_Text nameText,descriptionText,amountText; [SerializeField] Button useButton,sellButton; InventorySlot slot; InventoryService service; public void Show(InventorySlot s){slot=s;service=InventoryRuntime.Instance.Service;var d=service.GetDefinition(s.itemId);if(d==null)return;gameObject.SetActive(true);nameText.text=d.itemName;descriptionText.text=d.description;amountText.text=$"数量：{service.GetAmount(s.itemId)}";useButton.gameObject.SetActive(d.usable);sellButton.gameObject.SetActive(d.sellable);useButton.onClick.RemoveAllListeners();sellButton.onClick.RemoveAllListeners();useButton.onClick.AddListener(Use);sellButton.onClick.AddListener(Sell);}void Use(){var d=service.GetDefinition(slot.itemId);if(d!=null&&d.usable&&service.RemoveItem(slot.itemId,1))Show(slot);}void Sell(){var d=service.GetDefinition(slot.itemId);if(d!=null&&d.sellable&&service.RemoveItem(slot.itemId,1))Hide();}public void Hide(){slot=null;gameObject.SetActive(false);}}}
